def configure_determinism() -> dict:
    """One fixed inference configuration for every Q5 forward pass."""
    torch.backends.cudnn.benchmark = False
    torch.backends.cudnn.deterministic = True
    torch.backends.cuda.matmul.allow_tf32 = False
    torch.backends.cudnn.allow_tf32 = False
    try:
        torch.use_deterministic_algorithms(True)
        DETERMINISM["use_deterministic_algorithms"] = True
    except Exception as ex:                       # recorded, never hidden
        torch.use_deterministic_algorithms(True, warn_only=True)
        DETERMINISM["use_deterministic_algorithms"] = "warn_only (%s)" % type(ex).__name__
    return DETERMINISM


