def worse(a: str, b: str) -> str:
    """SECTION 4: the worse of two per-side states wins."""
    return a if _PRECEDENCE[a] >= _PRECEDENCE[b] else b


def sha256_file(p: str, buf: int = 1 << 20) -> str:
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for c in iter(lambda: f.read(buf), b""):
            h.update(c)
    return h.hexdigest()


def spec_revision() -> dict:
    d = json.load(open(FREEZE, encoding="utf-8"))
    now = sha256_file(os.path.join(HERE, "Q5_SPEC.md"))
    frozen = d["spec"]["Q5_SPEC.md"]
    if now != frozen:
        raise SystemExit("REFUSED: Q5_SPEC.md has drifted from its freeze.\n"
                         "  frozen %s\n  now    %s" % (frozen, now))
    return {"spec_sha256": frozen,
            "spec_frozen_utc": d["spec_frozen_utc"],
            "revisions": d.get("revisions", 1)}


# ------------------------------------------------------- SECTION 1: the resampler
def resample_declaration() -> dict:
    """Read RESAMPLE out of the frozen gate4_lib.py without importing it.

    Importing gate4_lib pulls the whole Gate 4 metric stack into this process.
    The parameters are a frozen literal, so they are parsed with `ast` and the
    file's sha256 is recorded beside them - which is stronger provenance than an
    import, because the hash is checked.
    """
    p = os.path.join(HERE, "gate4_lib.py")
    tree = ast.parse(open(p, encoding="utf-8").read())
    for node in tree.body:
        if isinstance(node, ast.Assign) and any(
                getattr(t, "id", None) == "RESAMPLE" for t in node.targets):
            params = ast.literal_eval(node.value)
            return {"params": params, "gate4_lib_sha256": sha256_file(p),
                    "read_by": "ast literal, not imported"}
    raise SystemExit("REFUSED: RESAMPLE not found in gate4_lib.py")


_RS = resample_declaration()
RESAMPLE = _RS["params"]


def _resample(t: torch.Tensor, sr_from: int, sr_to: int) -> torch.Tensor:
    if sr_from == sr_to:
        return t
    return torchaudio.functional.resample(
        t, sr_from, sr_to,
        lowpass_filter_width=RESAMPLE["lowpass_filter_width"],
        rolloff=RESAMPLE["rolloff"],
        resampling_method=RESAMPLE["resampling_method"],
        beta=RESAMPLE["beta"])


def load16(path: str) -> tuple[np.ndarray | None, str, float]:
    """SECTION 1 + SECTION 4. -> (signal @16k mono float32 | None, state, seconds)."""
    if not os.path.isfile(path):
        return None, NOT_MEASURED, 0.0
    wav, sr = sf.read(path, dtype="float32", always_2d=False)
    if wav.ndim > 1:
        wav = wav.mean(axis=1)
    if not np.all(np.isfinite(wav)):
        return None, UNKNOWN, float(len(wav)) / sr
    t = _resample(torch.from_numpy(np.ascontiguousarray(wav)).float().unsqueeze(0),
                  sr, SR)
    x = t.squeeze(0).numpy()
    dur = float(x.shape[-1]) / SR
    if not np.all(np.isfinite(x)):
        return None, UNKNOWN, dur
    if float(np.sqrt(np.mean(np.square(x, dtype=np.float64)))) == 0.0:
        return None, UNKNOWN, dur
    if dur < MIN_DUR_S:
        return None, INADMISSIBLE, dur
    return x, MEASURED, dur


