class Enc:
    """Model construction delegated to greek_tts/encoders.py; audio path is ours."""

    def __init__(self, name: str, device: str):
        if GREEK_TTS not in sys.path:
            sys.path.insert(0, GREEK_TTS)
        import encoders as GE                      # not modified
        self.name = name
        self.device = device
        self._e = GE.build(name, device)
        self.dim = int(GE.REGISTRY[name]["dim"])
        self.source = GE.REGISTRY[name]["source"]
        self.corpus = GE.TRAINING_CORPUS[name]
        ck = _CKPT_HINT[name]
        self.ckpt = ck
        self.ckpt_sha256 = sha256_file(ck) if os.path.isfile(ck) else "MISSING"

    def embed_signal(self, x: np.ndarray) -> np.ndarray:
        t = torch.from_numpy(np.ascontiguousarray(x)).float().unsqueeze(0)
        with torch.no_grad():
            v = self._e._fn(t.to(self.device))
        v = v.squeeze().float().cpu().numpy().astype(np.float64)
        n = float(np.linalg.norm(v))
        return (v / n).astype(np.float32) if n > 0 else v.astype(np.float32)

    def meta(self) -> dict:
        return {"encoder": self.name, "device": self.device, "dim": self.dim,
                "source": self.source, "training_corpus": self.corpus,
                "checkpoint": self.ckpt, "checkpoint_sha256": self.ckpt_sha256,
                "torch": torch.__version__, "torchaudio": torchaudio.__version__,
                "pooling": POOLING_ID}


def declared_devices() -> dict[str, str]:
    """SECTION 9.1: the device that passed the determinism probe is that
    encoder's declared device for EVERY subsequent step. Read from Q5_FUZZ.json,
    never chosen again."""
    p = os.path.join(HERE, "Q5_FUZZ.json")
    if not os.path.isfile(p):
        return {}
    d = json.load(open(p, encoding="utf-8"))
    return {n: r["device_declared"] for n, r in
            d.get("F1", {}).get("encoders", {}).items()
            if r.get("verdict") != "REMOVED"}


def build_panel(device: str | None = None) -> dict[str, Enc]:
    """Honours the F1-declared device per encoder unless one is forced."""
    dec = declared_devices()
    default = device or ("cuda" if torch.cuda.is_available() else "cpu")
    out = {}
    for n in ENCODERS:
        dev = device or dec.get(n, default)
        if dev == "cpu":
            torch.set_num_threads(1)      # the configuration that passed F1
        out[n] = Enc(n, dev)
    return out


# ------------------------------------------------------------ SECTION 10: cache
class Cache:
    """sha256(wav) . encoder . checkpoint sha . resampler . pooling . spec rev."""

    def __init__(self, path: str, spec_sha: str):
        self.path = path
        self.spec = spec_sha[:16]
        self.d: dict[str, np.ndarray] = {}
        if os.path.isfile(path):
            with np.load(path) as z:
                self.d = {k: z[k] for k in z.files}

    def key(self, wav_sha: str, enc: Enc, variant: str = "full") -> str:
        """SECTION 10: sha256 . encoder . checkpoint . DEVICE . resampler . pooling . spec.

        `device` is part of the identity from spec revision 3 on: SECTION 9.1 pins
        one device per encoder, and a cached embedding that cannot say which
        hardware produced it is not fully provenanced.

        `variant` names a declared transform of those bytes, never new bytes.

        The only variant Q5 uses is a duration-ladder prefix, e.g. "pre2s": the
        source side of a rung cell is the same prefix length as the rung, which
        is what GATE4_PREREG.md Q4 defines ("real 1 / 2 / 5 / 10 / 14 s prefixes
        of continuous recordings"). The bytes are still identified by sha256.
        """
        rs = "%s-%d-%g-%g" % (RESAMPLE["resampling_method"],
                              RESAMPLE["lowpass_filter_width"],
                              RESAMPLE["rolloff"], RESAMPLE["beta"])
        return "|".join([wav_sha, variant, enc.name, enc.ckpt_sha256[:16],
                         enc.device, rs, POOLING_ID, self.spec])

    def get(self, k: str):
        return self.d.get(k)

    def put(self, k: str, v: np.ndarray):
        self.d[k] = v.astype(np.float32)

    def save(self):
        np.savez_compressed(self.path, **self.d)


def cos(a: np.ndarray, b: np.ndarray) -> float:
    return float(np.dot(a.astype(np.float64), b.astype(np.float64)))


# ------------------------------------------------- SECTION 5: unit + uncertainty
def _two_level_median(values: list[float], groups: list[tuple]) -> float:
    """within (speaker x state) first, then across (SECTION 11.2.3)."""
    by: dict[tuple, list[float]] = {}
    for v, g in zip(values, groups):
        by.setdefault(g, []).append(v)
    inner = [float(np.median(v)) for v in by.values()]
    return float(np.median(inner)) if inner else float("nan")


def boot_recording_median(values: list[float], groups: list[tuple],
                          recs: list, seed: int = SEED,
                          n: int = N_RESAMPLES) -> dict:
    """Cluster bootstrap over RECORDINGS for a per-recording quantity."""
    uniq = sorted({r for r in recs})
    if len(uniq) < MIN_RECORDINGS:
        return {"n_recordings": len(uniq), "refused":
                "FEWER THAN %d DISTINCT ADMISSIBLE RECORDINGS" % MIN_RECORDINGS}
    idx: dict = {}
    for v, g, r in zip(values, groups, recs):
        idx.setdefault(r, []).append((v, g))
    point = _two_level_median(values, groups)
    rng = np.random.default_rng(seed)
    ui = np.array(range(len(uniq)))
    draws = np.empty(n, dtype=np.float64)
    for b in range(n):
        take = rng.choice(ui, size=len(uniq), replace=True)
        vs: list[float] = []
        gs: list[tuple] = []
        for t in take:
            for v, g in idx[uniq[t]]:
                vs.append(v)
                gs.append(g)
        draws[b] = _two_level_median(vs, gs)
    lo, hi = np.percentile(draws, [(100 - CI) / 2, 100 - (100 - CI) / 2])
    return {"n_recordings": len(uniq), "n_values": len(values),
            "median": point, "lo": float(lo), "hi": float(hi),
            "n_resamples": n, "seed": seed, "ci": CI}


def pair_groups(groups: list[tuple], pi: np.ndarray, pj: np.ndarray) -> np.ndarray:
    """SECTION 5.1: a pair's group is THE COMPONENTS ITS TWO MEMBERS SHARE.

    Within a state both members are (speaker, state) -> (speaker, state).
    Across states they share only the speaker -> (speaker,). Symmetric in i and
    j, so the estimator cannot depend on row order. Revision 4 used the
    lower-indexed member's group, which moved CROSS medians by up to 0.089 under
    permutation - enough to flip a label.
    """
    gi = [groups[i] for i in pi]
    gj = [groups[j] for j in pj]
    shared = [tuple(a for a, b in zip(x, y) if a == b) for x, y in zip(gi, gj)]
    idx = {g: k for k, g in enumerate(sorted(set(shared)))}
    return np.array([idx[g] for g in shared])


def boot_pair_median(M: np.ndarray, recs: list, groups: list[tuple],
                     pair_ok: np.ndarray, seed: int = SEED,
                     n: int = N_RESAMPLES) -> dict:
    """Cluster bootstrap for a PAIRWISE quantity - weighted form.

    Identical in result to `boot_pair_median_slow` below and enormously cheaper.
    Resampling a recording c times multiplies every pair it participates in by
    c, so a draw's induced pair multiset is exactly the original pair list with
    weights `c_i * c_j`. A weighted median over that is the same number as a
    plain median over the rebuilt multiset - and costs O(pairs) instead of
    rebuilding an n x n submatrix. The draw sequence is the same rng call, so
    the two implementations agree draw for draw, which `--check` verifies.
    """
    k = len(recs)
    if k == 0:
        return {"n_recordings": 0, "refused": "NO ADMISSIBLE ITEMS"}
    uniq = sorted(set(recs))
    if len(uniq) < MIN_RECORDINGS:
        return {"n_recordings": len(uniq), "refused":
                "FEWER THAN %d DISTINCT ADMISSIBLE RECORDINGS" % MIN_RECORDINGS}
    ridx = {r: i for i, r in enumerate(uniq)}
    recs_a = np.array([ridx[r] for r in recs])
    gidx = {g: i for i, g in enumerate(sorted(set(groups)))}
    grp_a = np.array([gidx[g] for g in groups])

    ok = pair_ok.copy()
    ok &= ~(recs_a[:, None] == recs_a[None, :])
    ok = np.triu(ok, 1)
    pi, pj = np.nonzero(ok)
    if pi.size == 0:
        return {"n_recordings": len(uniq), "refused": "NO ADMISSIBLE PAIRS"}
    val = M[pi, pj]
    pg = pair_groups(groups, pi, pj)
    ri, rj = recs_a[pi], recs_a[pj]

    order = np.argsort(val, kind="stable")
    val_s, pg_s, ri_s, rj_s = val[order], pg[order], ri[order], rj[order]
    gs = np.unique(pg_s)
    slots = [(g, np.nonzero(pg_s == g)[0]) for g in gs]

    def agg_weighted(c: np.ndarray) -> float:
        """Weighted median under numpy's own convention: for an even total the
        two central elements are AVERAGED. Anything else disagrees with
        `np.median` on the rebuilt multiset, and the two implementations must
        agree exactly, not approximately."""
        w_all = c[ri_s] * c[rj_s]
        inner = []
        for _g, idx in slots:
            w = w_all[idx]
            tot = int(w.sum())
            if tot <= 0:
                continue
            cw = np.cumsum(w)
            v = val_s[idx]
            if tot % 2 == 1:
                inner.append(float(v[int(np.searchsorted(cw, (tot + 1) // 2))]))
            else:
                a = v[int(np.searchsorted(cw, tot // 2))]
                b = v[int(np.searchsorted(cw, tot // 2 + 1))]
                inner.append(float(a + b) / 2.0)
        return float(np.median(inner)) if inner else float("nan")

    point = agg_weighted(np.ones(len(uniq), dtype=np.int64))
    if not np.isfinite(point):
        return {"n_recordings": len(uniq), "refused": "NO ADMISSIBLE PAIRS"}
    rng = np.random.default_rng(seed)
    draws = []
    for _ in range(n):
        take = rng.choice(len(uniq), size=len(uniq), replace=True)
        if len(set(take.tolist())) < MIN_RECORDINGS:
            continue
        v = agg_weighted(np.bincount(take, minlength=len(uniq)))
        if np.isfinite(v):
            draws.append(v)
    if len(draws) < n // 2:
        return {"n_recordings": len(uniq), "n_pairs": int(pi.size),
                "median": point,
                "refused": "TOO FEW ADMISSIBLE BOOTSTRAP DRAWS (%d of %d)"
                           % (len(draws), n)}
    lo, hi = np.percentile(np.array(draws), [(100 - CI) / 2, 100 - (100 - CI) / 2])
    return {"n_recordings": len(uniq), "n_pairs": int(pi.size), "median": point,
            "lo": float(lo), "hi": float(hi), "n_resamples": len(draws),
            "seed": seed, "ci": CI}


def boot_pair_median_slow(M: np.ndarray, recs: list, groups: list[tuple],
                          pair_ok: np.ndarray, seed: int = SEED,
                          n: int = N_RESAMPLES) -> dict:
    """Cluster bootstrap for a PAIRWISE quantity (SECTION 5).

    M          precomputed cosine matrix over items
    recs       recording id per item (ladder rungs share a recording id)
    groups     aggregation group per item, e.g. (speaker, state)
    pair_ok    boolean matrix: which (i, j) pairs the SECTION 3 rules admit
    """
    k = len(recs)
    if k == 0:
        return {"n_recordings": 0, "refused": "NO ADMISSIBLE ITEMS"}
    uniq = sorted(set(recs))
    if len(uniq) < MIN_RECORDINGS:
        return {"n_recordings": len(uniq), "refused":
                "FEWER THAN %d DISTINCT ADMISSIBLE RECORDINGS" % MIN_RECORDINGS}
    recs_a = np.array([uniq.index(r) for r in recs])
    gidx = {g: i for i, g in enumerate(sorted(set(groups)))}
    grp_a = np.array([gidx[g] for g in groups])

    def agg(sel: np.ndarray) -> float:
        ok = pair_ok[np.ix_(sel, sel)].copy()
        same_rec = recs_a[sel][:, None] == recs_a[sel][None, :]
        ok &= ~same_rec
        ok = np.triu(ok, 1)
        if not ok.any():
            return float("nan")
        gi, gj = np.nonzero(ok)
        vals = M[np.ix_(sel, sel)][gi, gj]
        gsel = [groups[i] for i in sel]
        gg = pair_groups(gsel, gi, gj)          # SECTION 5.1, same rule as the fast form
        inner = [float(np.median(vals[gg == g])) for g in np.unique(gg)]
        return float(np.median(inner)) if inner else float("nan")

    full = np.arange(k)
    point = agg(full)
    if not np.isfinite(point):
        return {"n_recordings": len(uniq), "refused": "NO ADMISSIBLE PAIRS"}
    n_pairs = int(np.triu(pair_ok & ~(recs_a[:, None] == recs_a[None, :]), 1).sum())
    rng = np.random.default_rng(seed)
    draws = []
    for _ in range(n):
        take = rng.choice(len(uniq), size=len(uniq), replace=True)
        if len(set(take.tolist())) < MIN_RECORDINGS:
            continue
        sel = np.concatenate([full[recs_a == t] for t in take])
        v = agg(sel)
        if np.isfinite(v):
            draws.append(v)
    if len(draws) < n // 2:
        return {"n_recordings": len(uniq), "n_pairs": n_pairs,
                "median": point,
                "refused": "TOO FEW ADMISSIBLE BOOTSTRAP DRAWS (%d of %d)"
                           % (len(draws), n)}
    lo, hi = np.percentile(np.array(draws), [(100 - CI) / 2, 100 - (100 - CI) / 2])
    return {"n_recordings": len(uniq), "n_pairs": n_pairs, "median": point,
            "lo": float(lo), "hi": float(hi), "n_resamples": len(draws),
            "seed": seed, "ci": CI}


# --------------------------------------------------------------- corpus helpers
def corpus() -> dict:
    return json.load(open(CORPUS, encoding="utf-8"))


def source_path(cell: dict) -> str:
    return os.path.join(SRC_ROOT, SEX[cell["speaker"]], cell["speaker"],
                        cell.get("lang", "English"), cell["state"], cell["file"])


def stem(speaker: str, state: str, index: int, rung_s=None) -> str:
    return "%s_%s_%04d%s" % (speaker, state, index,
                             "" if rung_s is None else "_%gs" % rung_s)


def recon_path(arm: str, setname: str, speaker: str, state: str, index: int,
               rung_s=None, condition: str = "offline") -> str:
    root = OFFLINE_ROOT if condition == "offline" else STREAM_ROOT
    suffix = "__offline.wav" if condition == "offline" else "__streamed.wav"
    return os.path.join(root, arm, setname,
                        stem(speaker, state, index, rung_s) + suffix)


def recording_id(cell: dict) -> tuple:
    """SECTION 11.2.1: the RECORDING, so ladder rungs share one id."""
    return (cell["speaker"], cell["state"], int(cell["index"]))


def arms(condition: str = "offline") -> list[str]:
    root = OFFLINE_ROOT if condition == "offline" else STREAM_ROOT
    return sorted(d for d in os.listdir(root)
                  if os.path.isdir(os.path.join(root, d)))
